select jsonb_build_object(
 'migrations',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations where version in ('20260813030004','20260813030005','20260813030006')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'security_definer',p.prosecdef,'search_path',p.proconfig,'public_execute',has_function_privilege('public',p.oid,'execute'),'anon_execute',has_function_privilege('anon',p.oid,'execute'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute')) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('crew_leave_submit','crew_leave_mobile','crew_leave_cancel','crew_leave_admin_data','crew_leave_review','crew_leave_block_roster_override','crew_leave_label','crew_leave_requested_days')),
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'anon_dml',has_table_privilege('anon',c.oid,'select,insert,update,delete'),'authenticated_dml',has_table_privilege('authenticated',c.oid,'select,insert,update,delete')) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('crew_leave_requests','crew_approved_leaves','crew_leave_roster_projections','crew_leave_audit'))
) crew_leave_security;
